<?php
function importNeed():void{if(!user())go('/login');if(user()['role']!=='admin'){http_response_code(403);exit('انتقال اطلاعات فقط برای مدیر کلینیک مجاز است.');}}
function importConfig():array{return q('SELECT * FROM import_connections WHERE id=1')->fetch();}
function importUrl(string $v,string $kind):string{$u=parse_url($v);$host=$kind==='login'?'account.boghrat.com':'app.boghrat.com';if(!$u||($u['scheme']??'')!=='https'||($u['host']??'')!==$host||isset($u['user'])||isset($u['pass'])||isset($u['port'])||isset($u['fragment']))throw new DomainException('فقط آدرس HTTPS رسمی بقراط مجاز است.');if($kind==='source'&&!str_starts_with($u['path']??'','/clinic/secretary/reception'))throw new DomainException('آدرس فهرست مراجعین بخش پذیرش را وارد کنید.');return $v;}
function importEncrypt(string $v):string{global $config;$iv=random_bytes(12);$tag='';$out=openssl_encrypt($v,'aes-256-gcm',hash('sha256',$config['secret'].'/boghrat-import',true),OPENSSL_RAW_DATA,$iv,$tag,'masiha-import');if($out===false)throw new RuntimeException('encrypt');return base64_encode($iv.$tag.$out);}
function importDecrypt(string $v):string{global $config;$raw=base64_decode($v,true);if($raw===false||strlen($raw)<29)throw new RuntimeException('credential');$out=openssl_decrypt(substr($raw,28),'aes-256-gcm',hash('sha256',$config['secret'].'/boghrat-import',true),OPENSSL_RAW_DATA,substr($raw,0,12),substr($raw,12,16),'masiha-import');if($out===false)throw new RuntimeException('credential');return $out;}
function importAccount(array $c):string{return hash('sha256',$c['username'].'|'.$c['source_url'].'|'.$c['clinic_name']);}
function importStatus($s):string{return ['paused'=>'متوقف','running'=>'در صف / در حال انتقال','blocked'=>'نیازمند بررسی دسترسی یا ورود','error'=>'متوقف به دلیل خطا','limit'=>'سقف تعیین‌شده تکمیل شد','complete'=>'پایان فهرست','space'=>'توقف به دلیل فضای ذخیره‌سازی'][$s]??$s;}
function importAction($a):bool{if(!str_starts_with($a,'import_'))return false;importNeed();global $db;
 if($a==='import_settings'){$db->beginTransaction();q('SELECT id FROM import_connections WHERE id=1 FOR UPDATE');$c=importConfig();if(q("SELECT id FROM import_runs WHERE status='running' LIMIT 1")->fetchColumn())throw new DomainException('ابتدا انتقال را متوقف کنید و سپس تنظیمات را تغییر دهید.');$login=importUrl(val('login_url',255,true),'login');$source=importUrl(val('source_url',512,true),'source');$username=MasihaOtp::digits(val('username',100,true));$password=val('password',200);$cipher=$password!==''?importEncrypt($password):$c['password_cipher'];if($username!==$c['username']&&$password==='')$cipher=null;if(isset($_POST['forget_password']))$cipher=null;q('UPDATE import_connections SET login_url=?,source_url=?,username=?,password_cipher=?,hourly_limit=?,total_limit=?,storage_mb=?,clinic_name=? WHERE id=1',[$login,$source,$username,$cipher,num('hourly_limit',1,300),num('total_limit',1,100000),num('storage_mb',16,2048),val('clinic_name',160,true)]);$db->commit();audit('import_settings_updated');flash('تنظیمات ذخیره شد. رمز فعلی هیچ‌گاه نمایش داده نمی‌شود.');go('/imports');}
 if($a==='import_start'||$a==='import_resume'){ $c=importConfig();if(!$c['username']||!$c['password_cipher']||!$c['clinic_name'])throw new DomainException('نام کاربری، رمز و نام دقیق کلینیک را در تنظیمات ذخیره کنید.');if(!is_file('/opt/masiha-importer/ready'))throw new DomainException('موتور انتقال هنوز نصب نشده است.');$db->beginTransaction();q('SELECT id FROM import_connections WHERE id=1 FOR UPDATE');if(q("SELECT id FROM import_runs WHERE status='running' LIMIT 1")->fetchColumn())throw new DomainException('یک انتقال فعال وجود دارد.');$key=importAccount($c);if($a==='import_resume'){$id=num('run_id',1);$r=q('SELECT * FROM import_runs WHERE id=? FOR UPDATE',[$id])->fetch();if(!$r||$r['account_key']!==$key)throw new DomainException('حساب یا کلینیک تغییر کرده؛ یک انتقال جدید بسازید.');if($r['status']==='complete')throw new DomainException('این پیمایش کامل شده است؛ برای بازبینی فهرست، انتقال جدید بسازید.');if((int)$r['processed']>=(int)$c['total_limit'])throw new DomainException('برای ادامه، سقف کل را بیشتر از تعداد پردازش‌شده تعیین کنید.');q("UPDATE import_runs SET status='running',hourly_limit=?,total_limit=?,storage_mb=?,message='ادامه از آخرین نقطه ثبت‌شده' WHERE id=?",[$c['hourly_limit'],$c['total_limit'],$c['storage_mb'],$id]);}else{q("INSERT INTO import_runs(account_key,status,hourly_limit,total_limit,storage_mb,created_by,message) VALUES(?,'running',?,?,?,?,?)",[$key,$c['hourly_limit'],$c['total_limit'],$c['storage_mb'],user()['id'],'در انتظار اجرای موتور انتقال']);$id=(int)$db->lastInsertId();}$db->commit();audit('import_requested',$id);flash('انتقال در صف قرار گرفت. موتور در کمتر از یک دقیقه وضعیت را بررسی می‌کند.');go('/imports');}
 if($a==='import_pause'){$id=num('run_id',1);q("UPDATE import_runs SET status='paused',message='توقف توسط مدیر؛ ذخیره رکورد جاری ممکن است تکمیل شود.' WHERE id=? AND status='running'",[$id]);audit('import_paused',$id);flash('توقف درخواست شد.');go('/imports');}
 if($a==='import_promote'){$id=num('record_id',1);$db->beginTransaction();$r=q('SELECT * FROM import_records WHERE id=? FOR UPDATE',[$id])->fetch();if(!$r)throw new DomainException('رکورد پیدا نشد.');if($r['pid'])throw new DomainException('این رکورد قبلاً به پرونده متصل شده است.');$pid=num('pid');if($pid){if(!q('SELECT pid FROM patients WHERE pid=?',[$pid])->fetchColumn())throw new DomainException('شماره پرونده مسیحا پیدا نشد.');}else{$fname=val('fname',80,true);$lname=val('lname',100,true);$mobile=$r['mobile']!==''?MasihaOtp::mobile($r['mobile']):null;$national=preg_match('/^\d{10}$/D',$r['national_id'])?$r['national_id']:null;if(($mobile&&q('SELECT pid FROM patients WHERE phone_cell=?',[$mobile])->fetchColumn())||($national&&q('SELECT pid FROM patients WHERE national_id=?',[$national])->fetchColumn()))throw new DomainException('شماره همراه یا کد ملی در مسیحا وجود دارد؛ پس از بررسی، شماره پرونده موجود را برای اتصال وارد کنید.');q("INSERT INTO patients(fname,lname,phone_cell,national_id,address,notes,created_by) VALUES(?,?,?,?,'',?,?)",[$fname,$lname,$mobile,$national,'اطلاعات منبع در آرشیو انتقال بقراط، رکورد '.$id.' محفوظ است.',user()['id']]);$pid=(int)$db->lastInsertId();}q('UPDATE import_records SET pid=? WHERE id=?',[$pid,$id]);$db->commit();audit('import_linked',$id);flash('رکورد به پرونده مسیحا متصل شد؛ محتوای منبع محفوظ است.');go('/imports?record='.$id);}
 return false;
}
function importsView():void{importNeed();$c=importConfig();$id=(int)($_GET['record']??0);layout('imports','انتقال اطلاعات از بقراط','دریافت اطلاعات قابل‌مشاهده، با سقف تعداد، ذخیره محلی و امکان ادامه.');if($id){$r=q('SELECT * FROM import_records WHERE id=?',[$id])->fetch();if(!$r){emptyState('رکورد پیدا نشد','');endLayout();return;}$data=json_decode($r['payload'],true)?:[];echo '<section class="panel form-panel"><h2>'.e($r['display_name']).'</h2><p>صفحه '.fa($r['source_page']).' · ردیف '.fa($r['source_row']+1).' · '.jd($r['updated_at'],'yyyy/MM/dd HH:mm').'</p><p class="notice">نسخه منبع برای بررسی نگهداری شده است. مبالغ سوابق به حسابداری مسیحا منتقل نشده‌اند.</p>';foreach(['personal'=>'اطلاعات شخصی و فرم‌های نمایان','history'=>'سوابق ویزیت و پرداختِ قابل‌مشاهده'] as $k=>$title){echo '<h2>'.$title.'</h2><pre class="import-text">'.e($data[$k]??'دریافت نشده').'</pre>';}echo '<h2>لینک‌های نمایان در پرونده</h2><ul>';foreach(($data['links']??[]) as $l){$url=$l['url']??'';$u=parse_url($url);if(($u['scheme']??'')==='https'&&in_array($u['host']??'',['app.boghrat.com','account.boghrat.com']))echo '<li><a target="_blank" rel="noopener noreferrer" href="'.e($url).'">'.e($l['text']??$url).'</a></li>';}echo '</ul><p class="hint">وجود لینک به معنای دریافت محتوای مقصد نیست. فایل‌ها در این مرحله دانلود نمی‌شوند.</p></section><section class="panel form-panel">';if($r['pid'])echo '<a class="button primary" href="/patient?id='.(int)$r['pid'].'">پرونده مسیحا شماره '.fa($r['pid']).'</a>';else{sectiontitle('ایجاد یا اتصال پرونده پس از بررسی');formstart('import_promote');hidden('record_id',$id);field('pid','شماره پرونده موجود در مسیحا',0,'number','صفر: ایجاد پرونده جدید. عدد دیگر: اتصال این آرشیو به همان پرونده.',true,false,'min="0"');field('fname','نام','','text','برای ساخت پرونده جدید، نام را مطابق مدرک بیمار وارد کنید.');field('lname','نام خانوادگی','','text','برای ساخت پرونده جدید ضروری است.');formend('ثبت اتصال پرونده','/imports');}echo '</section>';endLayout();return;}
 $r=q('SELECT * FROM import_runs ORDER BY id DESC LIMIT 1')->fetch();$sum=q('SELECT COUNT(*) n,COALESCE(SUM(bytes),0)+(SELECT COALESCE(SUM(bytes),0) FROM import_versions) bytes FROM import_records')->fetch();echo '<div class="stats-grid three"><article class="stat-card"><span>رکوردهای آرشیو محلی</span><strong>'.fa($sum['n']).'</strong></article><article class="stat-card"><span>حجم محتوای ذخیره‌شده</span><strong>'.fa(number_format($sum['bytes']/1048576,2)).'<small> مگابایت</small></strong></article><article class="stat-card"><span>آخرین وضعیت</span><strong style="font-size:18px">'.e($r?importStatus($r['status']):'هنوز شروع نشده').'</strong></article></div>';
 if($r){echo '<section class="panel form-panel"><h2>انتقال شماره '.fa($r['id']).'</h2><p>'.e($r['message']).'</p><p>بررسی‌شده: '.fa($r['processed']).' از '.fa($r['total_limit']).' · جدید: '.fa($r['saved']).' · قبلاً موجود: '.fa($r['duplicates']).' · نقطه ادامه: صفحه '.fa($r['page_no']).'، ردیف '.fa($r['row_no']+1).'</p>';if($r['not_before'])echo '<p>اجرای بعدی از '.jd($r['not_before'],'yyyy/MM/dd HH:mm:ss').'</p>';formstart($r['status']==='running'?'import_pause':'import_resume');hidden('run_id',$r['id']);formend($r['status']==='running'?'توقف انتقال':'ادامه انتقال','/imports');echo '</section>';}
 echo '<section class="panel form-panel">';sectiontitle('تنظیمات اتصال و محدودیت‌ها','نام دقیق کلینیک برای جلوگیری از انتقال اطلاعات مجموعه اشتباه بررسی می‌شود.');formstart('import_settings');echo '<div class="form-grid">';field('login_url','لینک ورود به بقراط',$c['login_url'],'url','فقط دامنه رسمی account.boghrat.com با HTTPS.',true);field('source_url','لینک فهرست مراجعین',$c['source_url'],'url','آدرس پذیرش با شناسه کلینیک، مطابق صفحه‌ای که خودتان باز کرده‌اید.',true);field('username','نام کاربری',$c['username'],'text','نام کاربری یا شماره همراه حساب بقراط.',true,false,'autocomplete="off"');field('password','پسورد بقراط','','password',$c['password_cipher']?'رمز قبلاً ذخیره شده؛ برای حفظ آن خالی بگذارید.':'رمز فقط در سرور با رمزنگاری ذخیره می‌شود؛ در گزارش یا بسته نصب قرار نمی‌گیرد.',false,false,'autocomplete="new-password"');field('clinic_name','نام دقیق کلینیک در بقراط',$c['clinic_name'],'text','دقیقاً مانند انتخابگر کلینیک در بالای صفحه بقراط.',true);field('hourly_limit','تعداد استخراج در هر ساعت',$c['hourly_limit'],'number','سقف بررسی پرونده‌ها در هر بازه ۶۰ دقیقه؛ از ۱ تا ۳۰۰. توقف و ادامه سهمیه را صفر نمی‌کند.',true,false,'min="1" max="300"');field('total_limit','تعداد کل استخراج در این انتقال',$c['total_limit'],'number','سقف پرونده‌های بررسی‌شده، شامل رکوردهای تکراری؛ از ۱ تا ۱۰۰۰۰۰.',true,false,'min="1" max="100000"');field('storage_mb','سقف آرشیو متنی (مگابایت)',$c['storage_mb'],'number','سقف مجموع محتوای آرشیو؛ علاوه بر آن حداقل ۵۱۲ مگابایت فضای دیسک باید آزاد بماند.',true,false,'min="16" max="2048"');echo '</div>';check('forget_password','حذف رمز ذخیره‌شده',false);formend('ذخیره تنظیمات','/imports');echo '</section><section class="panel form-panel">';sectiontitle('شروع انتقال جدید','برای بررسی اولیه، سقف کل را روی ۵ پرونده قرار دهید. شروع جدید از صفحه اول می‌رود و آرشیو قبلی را حذف نمی‌کند.');echo '<p>اطلاعات دو تب و لینک‌های نمایان ذخیره می‌شوند. لینک‌های مقصد، پیوست‌ها و فرم‌هایی که نیاز به بازکردن جداگانه دارند، فعلاً به‌عنوان «نیازمند بررسی» ثبت می‌شوند. تغییر ساختار صفحه یا پیام منع دسترسی، فرایند را متوقف می‌کند.</p>';echo '<p class="hint">ورود موفق در مرورگر شما به معنای ورود موتور سرور نیست. کپچا، پیامک یا تأیید دستگاه ممکن است مانع اجرای خودکار شود؛ ابزار آن‌ها را دور نمی‌زند.</p>';formstart('import_start');formend('شروع انتقال با تنظیمات ذخیره‌شده','/imports');echo '</section><section class="panel form-panel"><h2>آرشیو دریافت‌شده</h2><form method="get" class="search-form"><input name="q" aria-label="جستجوی آرشیو" placeholder="نام، شماره همراه یا کد ملی" value="'.e($_GET['q']??'').'"><button class="button secondary">جستجو</button></form>';$search=mb_substr(trim((string)($_GET['q']??'')),0,100);$page=max(1,(int)($_GET['p']??1));$where=$search!==''?'WHERE display_name LIKE ? OR mobile LIKE ? OR national_id LIKE ?':'';$args=$search!==''?array_fill(0,3,'%'.$search.'%'):[];$rows=q('SELECT id,display_name,confidence,completeness,pid,updated_at FROM import_records '.$where.' ORDER BY id DESC LIMIT 30 OFFSET '.(($page-1)*30),$args)->fetchAll();echo '<div class="table-scroll"><table><thead><tr><th>مراجعه</th><th>وضعیت</th><th>پرونده مسیحا</th><th></th></tr></thead><tbody>';foreach($rows as $x)echo '<tr><td>'.e($x['display_name']).'</td><td>'.($x['completeness']==='tabs_saved'?'دو تب دریافت شد؛ بررسی منبع لازم است':'دریافت ناقص / نیازمند بررسی').'</td><td>'.($x['pid']?fa($x['pid']):'هنوز متصل نشده').'</td><td><a class="text-link" href="?record='.$x['id'].'">بررسی اطلاعات</a></td></tr>';echo '</tbody></table></div><div class="pagination">';if($page>1)echo '<a href="?p='.($page-1).'&q='.urlencode($search).'">قبلی</a>';if(count($rows)===30)echo '<a href="?p='.($page+1).'&q='.urlencode($search).'">بعدی</a>';echo '</div></section>';endLayout();}
